64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
73	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
74	     * stored lower-cased.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /** A well-formed postcode: exactly four digits. */
80	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
81	
82	    /**
83	     * Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. A postcode supplied for an
84	     * owner whose city maps to one of these regions (see {@link LocalityLookup}) must fall within the
85	     * region's range; a city with no known region ({@code "UNKNOWN"}) accepts any 4-digit postcode.
86	     */
87	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
88	        "NSW", new int[] {2000, 2099},
89	        "VIC", new int[] {3000, 3099},
90	        "QLD", new int[] {4000, 4099});
91	
92	    /** Dedicated audit logger; one line is emitted per successful owner create. */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * The maximum number of owners a single city may contain. Once a city already holds this many
97	     * owners, any further create naming that city is rejected as a conflict.
98	     */
99	    private static final int MAX_OWNERS_PER_CITY = 50;
100	
101	    /**
102	     * The maximum number of owners that may be registered in a single day. Once this many owners
103	     * already carry today's registration date, any further create is rejected as too many requests.
104	     */
105	    private static final int MAX_OWNERS_PER_DAY = 100;
106	
107	    /**
108	     * The number of owners that must already be registered on today's business day before a response
109	     * carries a bulk-signup warning. Once more than this many owners already carry today's
110	     * registration date, responses set {@code bulkSignupWarning} true.
111	     */
112	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
113	
114	    private final ClinicService clinicService;
115	
116	    private final OwnerMapper ownerMapper;
117	
118	    private final PetMapper petMapper;
119	
120	    private final VisitMapper visitMapper;
121	
122	    public OwnerRestControllerV1(ClinicService clinicService,
123	                                 OwnerMapper ownerMapper,
124	                                 PetMapper petMapper,
125	                                 VisitMapper visitMapper) {
126	        this.clinicService = clinicService;
127	        this.ownerMapper = ownerMapper;
128	        this.petMapper = petMapper;
129	        this.visitMapper = visitMapper;
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
135	        Collection<Owner> owners;
136	        if (lastName != null) {
137	            owners = this.clinicService.findOwnerByLastName(lastName);
138	        } else {
139	            owners = this.clinicService.findAllOwners();
140	        }
141	        if (owners.isEmpty()) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        owners.forEach(owner -> owner.setHouseholdMemberCount(countHouseholdMembers(owner)));
145	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        OwnerDto ownerDto = toOwnerDto(owner);
156	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
157	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
163	        validateRequiredOwnerFields(ownerFieldsDto);
164	        LocalDate suppliedOrDefaultDate =
165	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
166	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
167	        rejectDailyLimitExceeded(registrationDate);
168	        rejectCityAtCapacity(ownerFieldsDto.getCity());
169	        HttpHeaders headers = new HttpHeaders();
170	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
171	        validatePostcode(owner.getCity(), owner.getPostcode());
172	        owner.setAddress(normalizeAddress(owner.getAddress()));
173	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
174	        owner.setTelephone(normalizedTelephone);
175	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
176	        owner.setEmail(normalizeEmail(owner.getEmail()));
177	        rejectDuplicateIdentity(owner);
178	        owner.setRegistrationDate(registrationDate);
179	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
180	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
181	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
182	        this.clinicService.saveOwner(owner);
183	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
184	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
185	        OwnerDto ownerDto = toOwnerDto(owner);
186	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
187	        headers.setLocation(UriComponentsBuilder.newInstance()
188	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
189	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
195	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
196	        if (currentOwner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        currentOwner.setAddress(ownerFieldsDto.getAddress());
200	        currentOwner.setCity(ownerFieldsDto.getCity());
201	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
202	        currentOwner.setLastName(ownerFieldsDto.getLastName());
203	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
204	        this.clinicService.saveOwner(currentOwner);
205	        return new ResponseEntity<>(toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Transactional
210	    @Override
211	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        this.clinicService.deleteOwner(owner);
217	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner == null) {
225	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	        }
227	        HttpHeaders headers = new HttpHeaders();
228	        Pet pet = petMapper.toPet(petFieldsDto);
229	        owner.setId(ownerId);
230	        pet.setOwner(owner);
231	        pet.getType().setName(null);
232	        this.clinicService.savePet(pet);
233	        PetDto petDto = petMapper.toPetDto(pet);
234	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
235	            .buildAndExpand(pet.getId()).toUri());
236	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
237	    }
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
242	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
243	        if (currentOwner != null) {
244	            Pet currentPet = this.clinicService.findPetById(petId);
245	            if (currentPet != null) {
246	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
247	                currentPet.setName(petFieldsDto.getName());
248	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
249	                this.clinicService.savePet(currentPet);
250	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
251	            }
252	        }
253	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	    }
255	
256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Override
258	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
259	        HttpHeaders headers = new HttpHeaders();
260	        Visit visit = visitMapper.toVisit(visitFieldsDto);
261	        Pet pet = new Pet();
262	        pet.setId(petId);
263	        visit.setPet(pet);
264	        this.clinicService.saveVisit(visit);
265	        VisitDto visitDto = visitMapper.toVisitDto(visit);
266	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
267	            .buildAndExpand(visit.getId()).toUri());
268	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
269	    }
270	
271	
272	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
273	    @Override
274	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
275	        Owner owner = this.clinicService.findOwnerById(ownerId);
276	        if (owner != null) {
277	            Pet pet = owner.getPet(petId);
278	            if (pet != null) {
279	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
280	            }
281	        }
282	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	    }
284	
285	    /**
286	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
287	     * offending field is collected so the caller learns exactly which values must be supplied.
288	     *
289	     * @param ownerFieldsDto the submitted owner payload
290	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
291	     *         telephone is missing or blank
292	     */
293	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
294	        List<String> missingFields = new ArrayList<>();
295	        if (isBlank(ownerFieldsDto.getFirstName())) {
296	            missingFields.add("firstName");
297	        }
298	        if (isBlank(ownerFieldsDto.getLastName())) {
299	            missingFields.add("lastName");
300	        }
301	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
302	            missingFields.add("address");
303	        }
304	        if (isBlank(ownerFieldsDto.getCity())) {
305	            missingFields.add("city");
306	        }
307	        if (isBlank(ownerFieldsDto.getTelephone())) {
308	            missingFields.add("telephone");
309	        }
310	        if (!missingFields.isEmpty()) {
311	            throw new MissingOwnerFieldsException(missingFields);
312	        }
313	    }
314	
315	    private boolean isBlank(String value) {
316	        return value == null || value.isBlank();
317	    }
318	
319	    /**
320	     * Counts the existing owners who, before this create, already share the given first and last name.
321	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
322	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
323	     * case or spacing still count as the same name.
324	     *
325	     * @param firstName the first name of the owner being created
326	     * @param lastName the last name of the owner being created
327	     * @return the number of existing owners sharing both names (zero when none)
328	     */
329	    private int countNamesakes(String firstName, String lastName) {
330	        String first = normalizeHouseholdField(firstName);
331	        String last = normalizeHouseholdField(lastName);
332	        return (int) this.clinicService.findAllOwners().stream()
333	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
334	                && normalizeHouseholdField(existing.getLastName()).equals(last))
335	            .count();
336	    }
337	
338	    /**
339	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
340	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
341	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
342	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
343	     * more owners the create is rejected as a conflict.
344	     *
345	     * @param city the city of the owner being created
346	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
347	     */
348	    /**
349	     * Rejects an owner create once the maximum number of owners have already been registered on the
350	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
351	     * which is always a business day (a weekend effective date is rolled forward to the following
352	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
353	     * business day the create is rejected as too many requests. Because a weekend effective date is
354	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
355	     *
356	     * @param businessDay the adjusted business day the owner being created would be registered on
357	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
358	     */
359	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
360	        long ownersOnDay = this.clinicService.findAllOwners().stream()
361	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
362	            .count();
363	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
364	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
365	        }
366	    }
367	
368	    /**
369	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
370	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
371	     * was supplied on the request or defaulted to the server's current date.
372	     *
373	     * @param date the effective registration date (supplied or defaulted)
374	     * @return the same date when it is a weekday, otherwise the following Monday
375	     */
376	    /**
377	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
378	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
379	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
380	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
381	     *
382	     * @return {@code true} when more than the threshold number of owners are already registered on
383	     *         today's business day, otherwise {@code false}
384	     */
385	    private boolean isBulkSignupWarningActive() {
386	        LocalDate today = toBusinessDay(LocalDate.now());
387	        long ownersToday = this.clinicService.findAllOwners().stream()
388	            .filter(existing -> today.equals(existing.getRegistrationDate()))
389	            .count();
390	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
391	    }
392	
393	    private LocalDate toBusinessDay(LocalDate date) {
394	        return switch (date.getDayOfWeek()) {
395	            case SATURDAY -> date.plusDays(2);
396	            case SUNDAY -> date.plusDays(1);
397	            default -> date;
398	        };
399	    }
400	
401	    private void rejectCityAtCapacity(String city) {
402	        String normalizedCity = normalizeHouseholdField(city);
403	        long ownersInCity = this.clinicService.findAllOwners().stream()
404	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
405	            .count();
406	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
407	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
408	        }
409	    }
410	
411	    /**
412	     * Builds an owner's customer code, formatted '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;'. CITY3 is
413	     * the upper-cased first three letters of the city; LAST3 is the upper-cased first three letters of
414	     * the last name; NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
415	     * of owners already in that city (e.g. 'SYD-SMI-0007').
416	     *
417	     * @param city the owner's city
418	     * @param lastName the owner's last name
419	     * @return the formatted customer code
420	     */
421	    private String generateCustomerCode(String city, String lastName) {
422	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
423	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
424	        String normalizedCity = normalizeHouseholdField(city);
425	        int sequence = (int) this.clinicService.findAllOwners().stream()
426	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
427	            .count() + 1;
428	        return String.format("%s-%s-%04d", city3, last3, sequence);
429	    }
430	
431	    /**
432	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
433	     * customerCode is the owner's customer code and YY is the last two digits of the
434	     * registrationDate year (e.g. 'SMI-0007-M26').
435	     *
436	     * @param customerCode the owner's customer code
437	     * @param registrationDate the owner's registration date
438	     * @return the formatted membership number
439	     */
440	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
441	        String yy = String.format("%02d", registrationDate.getYear() % 100);
442	        return customerCode + "-M" + yy;
443	    }
444	
445	    /**
446	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
447	     * country calling code. Australia ('+61') uses 9 national digits and the North American
448	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
449	     * E.164 length (8 to 15 digits overall).
450	     */
451	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
452	        java.util.Map.of("61", 9, "1", 10);
453	
454	    /**
455	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
456	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
457	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
458	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
459	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
460	     * E.164 string is what gets stored and returned.
461	     *
462	     * @param telephone the raw telephone value from the request
463	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
464	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
465	     *         national number has the wrong length for its country code
466	     */
467	    private String normalizeTelephone(String telephone) {
468	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
469	        String e164;
470	        if (cleaned.startsWith("+")) {
471	            e164 = cleaned;
472	        } else {
473	            String national = cleaned;
474	            if (national.startsWith("0")) {
475	                national = national.substring(1);
476	            }
477	            e164 = "+61" + national;
478	        }
479	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
480	            throw new InvalidOwnerFieldsException(List.of("telephone"));
481	        }
482	        validateNationalNumberLength(e164);
483	        return e164;
484	    }
485	
486	    /**
487	     * Rejects an E.164 telephone whose national number does not have the exact length its country
488	     * calling code requires. The digits after the leading '+' are split into the longest matching
489	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
490	     * code is known and the national number's length differs from the required count the telephone is
491	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
492	     *
493	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
494	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
495	     */
496	    private void validateNationalNumberLength(String e164) {
497	        String digits = e164.substring(1);
498	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
499	            String countryCode = digits.substring(0, codeLength);
500	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
501	            if (requiredNationalLength != null) {
502	                int nationalLength = digits.length() - codeLength;
503	                if (nationalLength != requiredNationalLength) {
504	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
505	                }
506	                return;
507	            }
508	        }
509	    }
510	
511	    /**
512	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
513	     * left unset. When a value is present it must be a syntactically valid address; the normalized
514	     * form stored and returned is the value lower-cased.
515	     *
516	     * @param email the raw email value from the request, or {@code null} when none was supplied
517	     * @return the lower-cased email, or {@code null} when no email was supplied
518	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
519	     */
520	    private String normalizeEmail(String email) {
521	        if (email == null || email.isBlank()) {
522	            return null;
523	        }
524	        if (!EMAIL_PATTERN.matcher(email).matches()) {
525	            throw new InvalidOwnerFieldsException(List.of("email"));
526	        }
527	        return email.toLowerCase(Locale.ROOT);
528	    }
529	
530	    /**
531	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
532	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
533	     * When present it must be exactly four digits and, when the owner's city maps to a known region
534	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
535	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
536	     * region accepts any four-digit postcode.
537	     *
538	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
539	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
540	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
541	     *         for the city's region
542	     */
543	    private void validatePostcode(String city, String postcode) {
544	        if (postcode == null || postcode.isBlank()) {
545	            return;
546	        }
547	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
548	            throw new InvalidOwnerFieldsException(List.of("postcode"));
549	        }
550	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
551	        if (range == null) {
552	            return;
553	        }
554	        int value = Integer.parseInt(postcode);
555	        if (value < range[0] || value > range[1]) {
556	            throw new InvalidOwnerFieldsException(List.of("postcode"));
557	        }
558	    }
559	
560	    /**
561	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
562	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
563	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
564	     * normalized form is what gets stored, returned and used for every address comparison (the
565	     * required-field check, household duplicate detection and the shared household id).
566	     *
567	     * @param address the raw address value from the request, or {@code null}
568	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
569	     */
570	    private String normalizeAddress(String address) {
571	        if (address == null) {
572	            return "";
573	        }
574	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
575	        if (collapsed.isEmpty()) {
576	            return "";
577	        }
578	        String[] tokens = collapsed.split(" ");
579	        for (int i = 0; i < tokens.length; i++) {
580	            switch (tokens[i]) {
581	                case "ST" -> tokens[i] = "STREET";
582	                case "RD" -> tokens[i] = "ROAD";
583	                case "AVE" -> tokens[i] = "AVENUE";
584	                default -> { }
585	            }
586	        }
587	        return String.join(" ", tokens);
588	    }
589	
590	    /**
591	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
592	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
593	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
594	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
595	     * so two members of one household with different telephones have different keys and are both
596	     * allowed; only an owner whose entire key is identical is a duplicate.
597	     *
598	     * @param owner the owner being created, with its telephone, email and householdId already resolved
599	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
600	     */
601	    private void rejectDuplicateIdentity(Owner owner) {
602	        String identityKey = owner.getIdentityKey();
603	        boolean inUse = this.clinicService.findAllOwners().stream()
604	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
605	        if (inUse) {
606	            throw new DuplicateOwnerIdentityException(identityKey);
607	        }
608	    }
609	
610	    /**
611	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
612	     * last name and a normalized address: last names are compared case-insensitively after whitespace
613	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
614	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
615	     * abbreviation still count as the same household.
616	     * <p>
617	     * When the owner's last name and address already belong to at least one other owner and
618	     * {@code sharesHousehold} is true, every member of the household - the existing owners and this
619	     * joiner - is assigned the same stable {@code householdId}, which is returned on read and forms
620	     * the third component of the {@code identityKey}. When {@code sharesHousehold} is not true, or no
621	     * other owner shares the last name and address, no identifier is assigned. Household membership no
622	     * longer rejects a create on its own; duplicates are detected solely through the identity key.
623	     *
624	     * @param owner the owner being created
625	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
626	     */
627	    /**
628	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
629	     * household member count} for the response.
630	     *
631	     * @param owner the owner to map
632	     * @return the mapped owner DTO
633	     */
634	    private OwnerDto toOwnerDto(Owner owner) {
635	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
636	        return ownerMapper.toOwnerDto(owner);
637	    }
638	
639	    /**
640	     * Counts the members of the given owner's household - the owners that share this owner's
641	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
642	     * is {@code null}) is its own sole member, so the count is one.
643	     *
644	     * @param owner the owner whose household is being sized
645	     * @return the number of owners sharing this owner's household (one when it has no household)
646	     */
647	    private int countHouseholdMembers(Owner owner) {
648	        String householdId = owner.getHouseholdId();
649	        if (householdId == null) {
650	            return 1;
651	        }
652	        return (int) this.clinicService.findAllOwners().stream()
653	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
654	            .count();
655	    }
656	
657	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
658	        String lastName = normalizeHouseholdField(owner.getLastName());
659	        String address = normalizeAddress(owner.getAddress());
660	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
661	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
662	                && normalizeAddress(existing.getAddress()).equals(address))
663	            .toList();
664	        if (housemates.isEmpty()) {
665	            return;
666	        }
667	        if (!Boolean.TRUE.equals(sharesHousehold)) {
668	            return;
669	        }
670	        String householdId = generateHouseholdId(lastName, address);
671	        owner.setHouseholdId(householdId);
672	        for (Owner housemate : housemates) {
673	            if (!householdId.equals(housemate.getHouseholdId())) {
674	                housemate.setHouseholdId(householdId);
675	                this.clinicService.saveOwner(housemate);
676	            }
677	        }
678	    }
679	
680	    /**
681	     * Builds the stable identifier shared by the members of one household. It is derived purely from
682	     * the normalized last name and address, so every owner of a given household deterministically
683	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
684	     * two normalized fields joined by a single space.
685	     *
686	     * @param normalizedLastName the household's last name, already normalized for comparison
687	     * @param normalizedAddress the household's address, already normalized for comparison
688	     * @return the shared household identifier
689	     */
690	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
691	        String key = normalizedLastName + '�' + normalizedAddress;
692	        try {
693	            byte[] digest = MessageDigest.getInstance("SHA-256")
694	                .digest(key.getBytes(StandardCharsets.UTF_8));
695	            StringBuilder hex = new StringBuilder();
696	            for (byte b : digest) {
697	                hex.append(String.format("%02X", b));
698	                if (hex.length() >= 12) {
699	                    break;
700	                }
701	            }
702	            return hex.substring(0, 12);
703	        } catch (NoSuchAlgorithmException e) {
704	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
705	        }
706	    }
707	
708	    /**
709	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
710	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
711	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
712	     * expands common abbreviations.
713	     *
714	     * @param value the raw last name, or {@code null}
715	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
716	     */
717	    private String normalizeHouseholdField(String value) {
718	        if (value == null) {
719	            return "";
720	        }
721	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
722	    }
723	}
